const hero=({cr,eyebrow,title,lead,img,cta=''})=>`<section class="ph"><div class="wrap">${crumbs(cr)}<div class="in"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="lead">${lead}</p>${cta?`<div class="cta">${cta}</div>`:''}</div><figure class="art tilt"><img src="${IMG[img]}" alt="${ALT[img]}" style="object-position:${POS[img]}"><figcaption>${CAP[img]}</figcaption></figure></div></div></section>`;
const sub=(items,cur)=>`<div class="subnav"><div class="wrap">${items.map(([l,h])=>`<a href="${H(h)}" class="${h===cur?'on':''}">${l}</a>`).join('')}</div></div>`;
const sec=(inner,cls='')=>`<section class="sec ${cls}"><div class="wrap">${inner}</div></section>`;
const head=(eb,t,s)=>`<div class="rv" style="margin-bottom:34px"><span class="eyebrow">${eb}</span><h2 class="h2">${t}</h2>${s?`<p class="sub">${s}</p>`:''}</div>`;
const card=(h,i,t,p,extra='',c='')=>`<a class="card rv" href="${H(h)}">${icon(i,c)}<h3>${t}</h3><p>${p}</p>${extra}<span class="go">Explore <span>→</span></span></a>`;
const pn=(prev,next)=>`<div class="pn">${prev?`<a href="${H(prev[1])}"><small>← Previous</small><b>${prev[0]}</b></a>`:'<span></span>'}${next?`<a class="n" href="${H(next[1])}"><small>Next →</small><b>${next[0]}</b></a>`:'<span></span>'}</div>`;
const closer=(t,p,h,l)=>`<div class="closing rv"><h2 class="h2" style="color:#fff;margin-top:0">${t}</h2><p>${p}</p><a class="btn p" href="${H(h)}">${l} →</a></div>`;
function table(head,rows){return `<div class="tw"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
const kv=rows=>`<div class="kv">${rows.map(r=>`<div>${r[0]}</div><div>${r[1]}</div>`).join('')}</div>`;
const LEARN=[["Fundamentals","learn/fundamentals"],["Evolution","learn/evolution"],["Customer journey","learn/journey"],["Metrics","learn/metrics"]];
/* stepper */
function stepper(root,det,data,extra,after){const el=$(root);el.innerHTML=data.map((d,i)=>`<button class="st" data-i="${i}" aria-pressed="false"><div class="dot">${ic(d[2])}</div><h4>${d[0]}</h4></button>`).join('');
const show=i=>{$$('.st',el).forEach((b,j)=>{b.classList.toggle('on',i===j);b.setAttribute('aria-pressed',i===j)});$(det).innerHTML=`<h3 style="font-size:24px">${i+1}. ${data[i][0]}</h3><p class="mut" style="margin-top:6px;font-size:17px">${data[i][1]}</p>`+(extra?extra(i):'');after&&after(i)};
el.onclick=e=>{const b=e.target.closest('.st');if(b)show(+b.dataset.i)};show(0);return show}

